:root {
  --ink: #26313a;
  --muted: #66747b;
  --paper: #ffffff;
  --line: #d9e2df;
  --mint: #dff3e9;
  --mint-ink: #24704f;
  --coral: #ef765f;
}

.slot-card {
  width: 460px;
  overflow: hidden;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 16px;
}

.slot-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 16px;
  border-bottom: 1px solid var(--line);
}

.paw-mark {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  background: var(--mint);
  border-radius: 10px;
  font-size: 20px;
}

.eyebrow,
.slot-header h1 {
  margin: 0;
}

.eyebrow {
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
}

.slot-header h1 {
  color: var(--ink);
  font-size: 19px;
  line-height: 1.2;
}

.slot-details,
.slot-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 13px 16px;
  color: var(--muted);
  font-size: 14px;
}

.slot-details strong {
  color: var(--ink);
}

.slot-footer {
  background: var(--mint);
}

.status {
  color: var(--mint-ink);
  font-weight: 700;
}

button {
  padding: 7px 12px;
  color: var(--paper);
  background: var(--coral);
  border: 0;
  border-radius: 8px;
  font: inherit;
  font-weight: 700;
}
